import 'dart:async';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Where the Node half is listening, as reported by the Android side.
///
/// The token is generated by Node on every run, so it cannot be compiled in:
/// it has to be read from the discovery file the runtime writes after `listen`.
class HostEndpoint {
  final String socketPath;
  final String token;
  final int pid;

  const HostEndpoint({required this.socketPath, required this.token, this.pid = -1});

  @override
  String toString() => 'HostEndpoint($socketPath, pid=$pid)';
}

/// Brings the embedded runtime up and hands back its socket.
///
/// On Android a cold start is minutes of work (a 16 452-file unpack, then
/// libnode, then the socket), so this is deliberately two calls: `startHarness`
/// returns immediately and `awaitReady` blocks on the native side until the
/// runtime is usable. Dart never polls the endpoint itself.
///
/// Everywhere else the channel is missing and the result is `null`, which is
/// what keeps `flutter test` and desktop builds working without a platform layer.
///
/// Failure is not an exception: a runtime that cannot start is a degraded app,
/// not a crash, so every path returns null and the reason lands in [status].
class HostBootstrap {
  static const MethodChannel channel = MethodChannel('ai.dsh/host');

  /// Coarse state for the UI. Deliberately a string, not an enum: it is
  /// diagnostic text that a settings row can show verbatim.
  static final ValueNotifier<String> status = ValueNotifier<String>('not started');

  static bool get isSupported {
    // Only the Android shell implements the channel; asking anywhere else
    // costs a MissingPluginException round-trip on every launch.
    if (kIsWeb) return false;
    return defaultTargetPlatform == TargetPlatform.android ||
        defaultTargetPlatform == TargetPlatform.iOS;
  }

  /// Starts the runtime if needed and waits for it to become usable.
  ///
  /// Returns null when the platform has no runtime, the service refuses to
  /// start, the runtime failed, or it never became ready inside [timeout].
  /// [timeout] defaults to 240 s because a cold start is a file-copy problem,
  /// not a network problem: 8 s (the old default) could never succeed.
  static Future<HostEndpoint?> ensureRunning({
    Duration timeout = const Duration(seconds: 240),
  }) async {
    if (!isSupported) {
      status.value = 'no embedded runtime on this platform';
      return null;
    }
    Timer? ticker;
    try {
      final paths = await channel.invokeMapMethod<String, dynamic>('paths');
      // 与桌面客户端一致的装配文案；不 import boot_screen.dart 取常量，
      // 那会让底层 host 模块反向依赖 UI 层（boot_screen 已经 import 了本文件）。
      status.value = 'Loading plugins...';
      await channel.invokeMethod<bool>('startHarness');

      // Progress: the native side polls readiness, but it only learns *how far*
      // the unpack got from the status file. Refreshing it here is what turns a
      // static "starting" label into "正在解压运行时 (3500/16452)".
      _booting = true;
      ticker = Timer.periodic(const Duration(seconds: 1), (_) => unawaited(_refreshStatus()));

      final ready = await channel.invokeMapMethod<String, dynamic>(
        'awaitReady',
        <String, dynamic>{'timeoutMs': timeout.inMilliseconds},
      );
      // Settle the label first: a refresh that was already in flight must not
      // overwrite "已就绪" with a stale "正在启动".
      _booting = false;
      final rawStatus = ready?['status'];
      _applyStatus(rawStatus is Map ? rawStatus : null);

      final raw = ready?['endpoint'];
      if (raw is! Map) {
        // A reported failure keeps its own message; a timeout keeps the last
        // step, so "启动超时：正在解压运行时 (3500/16452)" reads as slow, not broken.
        final state = rawStatus is Map ? rawStatus['state'] : null;
        if (state != 'failed') status.value = '启动超时：${status.value}';
        debugPrint('[host] runtime not ready (${paths?['filesDir'] ?? '?'})');
        return null;
      }
      final socket = raw['socket'] as String? ?? '';
      final token = raw['token'] as String? ?? '';
      if (socket.isEmpty || token.isEmpty) {
        status.value = '运行时发布的 endpoint 不完整';
        return null;
      }
      status.value = '已就绪';
      return HostEndpoint(socketPath: socket, token: token, pid: (raw['pid'] as int?) ?? -1);
    } on MissingPluginException {
      status.value = 'no embedded runtime on this platform';
      return null;
    } catch (e) {
      status.value = '启动失败：$e';
      return null;
    } finally {
      _booting = false;
      ticker?.cancel();
    }
  }

  /// One-shot read of the harness status file.
  ///
  /// Returns null when the platform is absent, the file does not exist yet, or
  /// it could not be parsed — "unknown" is a valid answer here, not an error.
  static Future<Map<String, dynamic>?> readStatus() async {
    if (!isSupported) return null;
    try {
      return await channel.invokeMapMethod<String, dynamic>('status');
    } on MissingPluginException {
      return null;
    } catch (_) {
      return null;
    }
  }

  /// 直接读一次 endpoint 文件，**不等待、不轮询**。
  ///
  /// 用途只有一个：桥的握手被拒之后，确认运行时有没有重新发布过 endpoint
  /// （token 每个 node 进程重新生成，服务被系统重启后旧 token 就对不上了）。
  ///
  /// 刻意不复用 [ensureRunning]：它内部走 `awaitReady`，那个要阻塞到就绪或
  /// 超时（默认 240 s）；在「重试一次握手」这条路上，那是把一次毫秒级重连变成
  /// 一次两分钟的假死。
  static Future<HostEndpoint?> readEndpoint() async {
    if (!isSupported) return null;
    try {
      final raw = await channel.invokeMapMethod<String, dynamic>('endpoint');
      if (raw == null) return null;
      final socket = raw['socket'] as String? ?? '';
      final token = raw['token'] as String? ?? '';
      if (socket.isEmpty || token.isEmpty) return null;
      return HostEndpoint(
        socketPath: socket,
        token: token,
        pid: (raw['pid'] as int?) ?? -1,
      );
    } on MissingPluginException {
      return null;
    } catch (_) {
      return null;
    }
  }

  /// Maps the raw status file onto the human-facing [status] string.
  static void _applyStatus(Map<dynamic, dynamic>? raw) {
    if (raw == null) return;
    final done = raw['done'];
    final total = raw['total'];
    final message = raw['message'];
    switch (raw['state']) {
      case 'unpacking':
        status.value = (done is int && total is int && total > 0)
            ? '正在解压运行时 ($done/$total)'
            : '正在解压运行时';
        break;
      case 'starting':
        // 与桌面客户端一致的装配文案（见上方 startHarness 前的同名赋值）。
        status.value = 'Loading plugins...';
        break;
      case 'running':
        // node is up but the socket is not published yet; awaitReady covers it.
        // 这一段同样是「解包完成 → 界面连上」之间的装配窗口，同一规则。
        status.value = 'Loading plugins...';
        break;
      case 'failed':
        status.value = '启动失败：${(message is String && message.isNotEmpty) ? message : '未知原因'}';
        break;
    }
  }

  static bool _refreshing = false;
  static bool _booting = false;

  /// Refresh [status] from the file, skipping a tick if the previous read is
  /// still in flight (a slow channel must not queue up calls every second).
  static Future<void> _refreshStatus() async {
    if (!_booting || _refreshing) return;
    _refreshing = true;
    try {
      final snapshot = await readStatus();
      // The wait may have finished while this read was in flight; in that case
      // the final label wins and this snapshot is dropped.
      if (_booting) _applyStatus(snapshot);
    } finally {
      _refreshing = false;
    }
  }

  /// 这次启动是否需要解包运行时。
  ///
  /// 只有首次安装与 APK 升级后为 true（展开 16 453 个文件，30-40 秒）；平时
  /// 启动是 false，一两秒就能连上。加载页据此决定显示完整清单还是极简启动态 ——
  /// 不该让每天都要开一次 App 的人看九步进度。
  ///
  /// 返回 null 表示问不到（桌面 / 测试 / 通道异常）：调用方按"可能需要解包"
  /// 处理，宁可多显示一次清单，也不要白屏。
  static Future<bool?> needsUnpack() async {
    if (!isSupported) return null;
    try {
      final info = await channel.invokeMapMethod<String, dynamic>('bootInfo');
      final value = info?['needsUnpack'];
      return value is bool ? value : null;
    } on MissingPluginException {
      return null;
    } catch (_) {
      return null;
    }
  }

  /// harness.log 的尾部。状态页每秒读一次，所以缺省只要最后 16 KB ——
  /// 整份搬运会把一次「刷新一行字」变成一次几 MB 的字符串拷贝。
  ///
  /// [maxChars] 传 0 表示要全文（原生侧封顶 2 MB 并在截断时首行注明），
  /// 「下载日志」走这条；UI 轮询保持缺省值。
  static Future<String> readLog({int maxChars = 16384}) async {
    if (!isSupported) return '';
    try {
      return await channel.invokeMethod<String>(
            'log',
            <String, dynamic>{'maxChars': maxChars},
          ) ??
          '';
    } catch (_) {
      return '';
    }
  }

  /// 把一段文本写进用户看得见的目录（Android 10+ 落 `下载/DSH Android/`）。
  ///
  /// 为什么不静默失败：0.1.22 的「查看日志」点了没反应，用户拿不到任何东西，
  /// 也就没法把问题带回来。这里把成功路径与失败原因都做成返回值，由 UI 直接
  /// 显示 —— 保存日志这件事的价值全在「用户能把文件发给我们」。
  static Future<LogSave> saveLog({
    required String text,
    required String name,
  }) async {
    if (!isSupported) return const LogSave.failed('当前平台没有原生日志目录');
    try {
      final path = await channel.invokeMethod<String>(
        'saveLog',
        <String, dynamic>{'text': text, 'name': name},
      );
      if (path == null || path.isEmpty) {
        return const LogSave.failed('原生侧没有返回保存位置');
      }
      return LogSave.saved(path);
    } on MissingPluginException {
      // 装了旧版壳层时会出现：方法在 Dart 侧存在、原生侧没有。
      return const LogSave.failed('当前安装的原生壳层不支持保存日志');
    } on PlatformException catch (e) {
      return LogSave.failed(e.message?.isNotEmpty == true ? e.message! : e.code);
    } catch (e) {
      return LogSave.failed('$e');
    }
  }
}

/// [HostBootstrap.saveLog] 的结果：拿到路径就是成功，拿到原因就是失败。
///
/// 不用「返回 null 表示失败 + 抛异常表示另一种失败」：调用方只关心
/// 「显示哪句话」，一个值带两种含义会让 UI 里长出两个分支。
class LogSave {
  /// 原生侧返回的展示用路径（`下载/DSH Android/dsh-log-….txt`）。
  final String? path;

  /// 失败原因（可读中文，直接显示）。
  final String? error;

  const LogSave.saved(String this.path) : error = null;

  const LogSave.failed(String this.error) : path = null;

  bool get ok => path != null;

  @override
  String toString() => ok ? 'LogSave($path)' : 'LogSave.failed($error)';
}
